        contentTh: [
          'การบริหารจัดการอัตลักษณ์และการเข้าถึง (Identity and Access Management: IAM) เริ่มต้นตั้งแต่ก่อนที่พนักงานจะมีบัญชีใช้งานจริงไปจนถึงวันที่ออกจากองค์กร หลักคิดสำคัญใน SY0-701 Objective 4.6 คือบัญชีผู้ใช้และสิทธิ์การเข้าถึงไม่ควรถูกสร้างและปล่อยทิ้งไว้ตลอดกาล แต่ต้องมีวงจรชีวิตที่ควบคุมได้ (Joiner-Mover-Leaver Lifecycle) เพื่อปิดช่องโหว่จากบัญชีค้าง (Orphaned Accounts) และการสะสมสิทธิ์เกินจำเป็น (Privilege Creep)',
          'Provisioning คือกระบวนการสร้างบัญชีผู้ใช้ กำหนดอัตลักษณ์เริ่มต้น และเชื่อมโยงไปยังระบบที่จำเป็นต้องใช้งานเมื่อมีพนักงานใหม่ คู่ค้า หรือบัญชีบริการเกิดขึ้น ในองค์กรขนาดใหญ่ควรผูกการ Provisioning เข้ากับระบบทรัพยากรบุคคล (HRIS) เป็นแหล่งความจริงหลัก (Source of Truth) เพื่อลดความผิดพลาดจากการสร้างบัญชีด้วยมือ คู่ขนานกับการสร้างบัญชีคือ Permission Assignments (การกำหนดสิทธิ์) ซึ่งควรจัดสรรผ่านกลุ่มหรือบทบาทงาน (Groups/Roles) ตามหลักสิทธิ์น้อยที่สุด (Least Privilege) แทนการคัดลอกสิทธิ์จากเพื่อนร่วมงานคนอื่นซึ่งมักทำให้สิทธิ์ที่ไม่เกี่ยวข้องติดมาด้วย',
          'เมื่อเวลาผ่านไป พนักงานอาจย้ายแผนก (Mover) หรือลาออก/สิ้นสุดสัญญา (Leaver) หากองค์กรขาดกระบวนการ De-provisioning (การเพิกถอนบัญชีและสิทธิ์) ที่รวดเร็วและสม่ำเสมอ จะเกิดบัญชีตกค้างที่พนักงานเก่าหรือผู้ไม่หวังดีสามารถใช้กลับเข้ามาในระบบหรือข้อมูลคลาวด์ได้ แม้พนักงานที่ย้ายแผนกก็อาจสะสมสิทธิ์ของแผนกเดิมควบคู่กับแผนกใหม่จนกลายเป็น Privilege Creep ดังนั้น De-provisioning ต้องครอบคลุมทั้งการปิดบัญชี IdP การยกเลิก Token เซสชัน การถอดสิทธิ์เข้าแอป SaaS และการเก็บกุญแจคืนทันทีเมื่อพ้นสภาพ',
          'อีกกลไกหนึ่งที่เชื่อมวงจรชีวิตให้สมบูรณ์คือ Attestation (การรับรองยืนยันสิทธิ์และความถูกต้องอย่างเป็นทางการ) ในบริบท IAM การทำ Access Attestation หมายถึงการทบทวนเป็นรอบระยะเวลา (เช่น ทุกไตรมาสหรือทุกปี) โดยให้หัวหน้างานหรือเจ้าของข้อมูล (Data Owner) ลงนามยืนยันอย่างเป็นทางการว่าบัญชีและสิทธิ์ที่ลูกทีมถือครองอยู่นั้น "ยังคงจำเป็นและถูกต้องอยู่จริง" หากไม่ยืนยันภายในกำหนด ระบบจะระงับสิทธิ์นั้นโดยอัตโนมัติ นอกจากนี้คำว่า Attestation ยังใช้ในเชิงการรับรองความสมบูรณ์ของตัวตนหรือสถานะอุปกรณ์ (Device/Identity Attestation) เพื่อพิสูจน์ต่อระบบผู้ตรวจสอบว่าบัญชีหรืออุปกรณ์ยังคงตรงตามนโยบายที่กำหนดไว้'
        ],
        keyPointsTh: [
          'Provisioning/De-provisioning ควรเชื่อมโยงกับวงจร Joiner-Mover-Leaver เพื่อป้องกันบัญชีค้าง (Orphaned Accounts) และ Privilege Creep',
          'Permission Assignments ควรจัดผ่านบทบาท/กลุ่มตามหลัก Least Privilege แทนการคัดลอกสิทธิ์จากบัญชีผู้อื่นแบบรายบุคคล',
          'Attestation คือกระบวนการทบทวนและรับรองสิทธิ์หรือสถานะอัตลักษณ์อย่างเป็นทางการตามรอบเวลา เพื่อถอนสิทธิ์ที่หมดความจำเป็น'
        ]
